def show(mask, step=4):
    for r in range(0, mask.shape[0], step):
        row=""
        for c in range(0, mask.shape[1], step):
            b = mask[r:r+step, c:c+step].mean()
            row += "#" if b>0.5 else ("." if b>0 else " ")
        print(row)
